# Fractional seconds (DATETIME(n), TIMESTAMP(n), TIME(n)), the forms of a date, a time and a year, the INTERVAL / EXTRACT units, GET_FORMAT, MAKETIME, and the
# column types and index options a real schema writes (R41). A line is a statement, '--' a setup statement run on both.
--CREATE TABLE fs (id INT PRIMARY KEY, a DATETIME(3), b TIMESTAMP(6) NULL, c TIME(2), d DATETIME, e TIME)
INSERT INTO fs VALUES (1, '2024-02-29 13:45:10.678912', '2024-02-29 13:45:10.123456', '13:45:10.678', '2024-02-29 13:45:10.678', '13:45:10.5')
INSERT INTO fs VALUES (2, '2024-12-31 23:59:59.9996', '2024-12-31 23:59:59.9999995', '23:59:59.996', '2024-12-31 23:59:59.5', '838:59:58.6')
INSERT INTO fs VALUES (3, '2024-02-29 13:45:10', NULL, '1 02:03:04.5', '2024-02-29', '-00:00:00.4')
INSERT INTO fs VALUES (4, '9999-12-31 23:59:59.9996', NULL, '838:59:59.99', '9999-12-31 23:59:59.5', '839:00:00')
INSERT INTO fs VALUES (5, 20240229134510, NULL, 1345, 20240229, 134510)
INSERT INTO fs VALUES (6, '24-02-29 1:2:3', NULL, '5', '240229', '1234')
INSERT INTO fs VALUES (7, '240229134510.5', NULL, '12:34', '20240229134510', '-1 1')
SELECT * FROM fs ORDER BY id
SELECT id, a > '2024-02-29 13:45:10.678', a = '2024-02-29 13:45:10.679', c = '13:45:10.68' FROM fs WHERE id = 1
SELECT MICROSECOND(a), MICROSECOND(c), MICROSECOND(e), MICROSECOND('2024-01-01 00:00:00.000123'), MICROSECOND('12:00:00.5') FROM fs WHERE id = 1
--CREATE TABLE tm (id INT PRIMARY KEY, dt DATETIME, ts TIMESTAMP NULL, tt TIME, d DATE, y YEAR)
INSERT INTO tm VALUES (1, '2024-02-29 13:45:10.678', '2024-02-29 13:45:10.4', '13:45:10.5', '2024-02-29', 2024)
INSERT INTO tm VALUES (2, '2024-02-29T13:45:10', '2024-02-29 13:45', '13:45', '2024/02/29', '24')
INSERT INTO tm VALUES (3, '2024-2-9 3:4:5', '20240229134510', '134510', '20240229', 70)
INSERT INTO tm VALUES (4, '2024-02-29', NULL, '-838:59:59', '0000-00-00', 0)
INSERT INTO tm VALUES (5, 20240229134510, 20240229, 1345, 20240229, 2155)
INSERT INTO tm (id, dt) VALUES (6, '2024-13-01 00:00:00')
INSERT INTO tm (id, dt) VALUES (7, '2024-02-30 00:00:00')
INSERT INTO tm (id, tt) VALUES (8, '839:00:00')
INSERT INTO tm (id, y) VALUES (9, 1900)
INSERT INTO tm (id, d) VALUES (10, 'abc')
SELECT * FROM tm ORDER BY id
SELECT id, dt > '2024-02-29 13:45:10', dt = '2024-02-29 13:45:11', DATE(dt) = d, TIME(dt) FROM tm WHERE id = 1
SELECT DATE_ADD('2024-01-31 10:00:00', INTERVAL '1:30' HOUR_MINUTE), DATE_ADD('2024-01-01', INTERVAL '1 12' DAY_HOUR), DATE_SUB('2024-01-01 00:00:00', INTERVAL '1 1:1:1' DAY_SECOND), DATE_ADD('2024-01-01', INTERVAL '2-3' YEAR_MONTH), DATE_ADD('2024-01-01 00:00:00', INTERVAL '1.5' SECOND_MICROSECOND), DATE_ADD('2024-01-01 00:00:00', INTERVAL '90' MINUTE_SECOND), DATE_ADD('2024-01-01', INTERVAL '-1:30' HOUR_MINUTE), '2024-01-01' + INTERVAL '1:1' MINUTE_SECOND
SELECT DATE_ADD('2024-01-31', INTERVAL 1 MONTH), DATE_ADD('2024-03-31', INTERVAL -1 MONTH), '2024-01-31' + INTERVAL 1 MONTH, DATE_ADD('2024-02-29', INTERVAL 1 YEAR), DATE_SUB('2024-03-01', INTERVAL 1 DAY), ADDDATE('2024-01-01', 31), SUBDATE('2024-01-01', INTERVAL 1 WEEK), DATE_ADD('2024-01-01 10:00:00', INTERVAL '1:30' HOUR_MINUTE)
SELECT EXTRACT(DAY_HOUR FROM '2024-02-29 13:45:10'), EXTRACT(DAY_MINUTE FROM '2024-02-29 13:45:10'), EXTRACT(DAY_SECOND FROM '2024-02-29 13:45:10'), EXTRACT(HOUR_MINUTE FROM '2024-02-29 13:45:10'), EXTRACT(HOUR_SECOND FROM '2024-02-29 13:45:10'), EXTRACT(MINUTE_SECOND FROM '2024-02-29 13:45:10'), EXTRACT(SECOND_MICROSECOND FROM '2024-02-29 13:45:10.123456'), EXTRACT(DAY_MICROSECOND FROM '2024-02-29 13:45:10.123456'), EXTRACT(HOUR_MICROSECOND FROM '2024-02-29 13:45:10.5'), EXTRACT(MINUTE_MICROSECOND FROM '2024-02-29 13:45:10.5'), EXTRACT(YEAR_MONTH FROM '2024-02-29')
SELECT EXTRACT(HOUR FROM '2024-02-29 13:45:10'), EXTRACT(MICROSECOND FROM '2024-02-29 13:45:10.123456'), EXTRACT(WEEK FROM '2024-02-29'), EXTRACT(QUARTER FROM '2024-02-29'), MICROSECOND('12:00:00.5')
SELECT GET_FORMAT(DATE, 'USA'), GET_FORMAT(DATE, 'EUR'), GET_FORMAT(DATE, 'ISO'), GET_FORMAT(DATETIME, 'JIS'), GET_FORMAT(TIME, 'USA'), GET_FORMAT(TIME, 'INTERNAL'), GET_FORMAT(DATETIME, 'xx'), DATE_FORMAT('2024-02-29 13:45:10', GET_FORMAT(DATETIME, 'USA'))
SELECT MAKETIME(12, 15, 30), MAKETIME(-5, 3, 4.25), MAKETIME(900, 0, 0), MAKETIME(1, 60, 0), MAKETIME(1, 2, 60), MAKETIME(0, 0, 0.5), MAKETIME(NULL, 1, 1)
SELECT TIMESTAMP('2024-02-29'), TIMESTAMP('2024-02-29 13:45:10.5'), TIMESTAMP('2024-02-29', '12:00:00'), TIMESTAMP('2024-02-29 23:00:00', '02:30:00'), TIMESTAMP('2024-02-29 10:00:00', '-01:00:00'), TIMESTAMP('xx')
SELECT LENGTH(NOW(3)), LENGTH(NOW(6)), LENGTH(NOW()), LENGTH(CURTIME(2)), LENGTH(CURRENT_TIMESTAMP(1)), LENGTH(UTC_TIMESTAMP(4)), LENGTH(SYSDATE(5)), LENGTH(CURRENT_TIME(3)), LENGTH(UTC_TIME(1)), NOW(3) >= NOW(0)
SELECT LENGTH(CURRENT_TIME), LENGTH(CURRENT_DATE), CURRENT_TIME >= '00:00:00', LENGTH(CURRENT_TIMESTAMP), LENGTH(LOCALTIME), LENGTH(LOCALTIMESTAMP(2))
SELECT CAST('2024-02-29 13:45:10.678' AS DATETIME), CAST('2024-02-29 13:45:10.678' AS DATETIME(3)), CAST('2024-02-29 13:45:10.678' AS DATETIME(1)), CAST('13:45:10.678' AS TIME), CAST('13:45:10.678' AS TIME(2)), CAST('2024-02-29 23:59:59.9' AS DATE), CAST('2024-02-29' AS DATETIME(2))
SELECT CAST('13:45:10' AS TIME), CAST('2024-02-29 23:59:59.9' AS DATETIME), CAST('999' AS YEAR), CAST(2024 AS YEAR), CAST('-01:30:00' AS TIME), CAST('xx' AS TIME), CAST('xx' AS DATETIME)
SELECT SEC_TO_TIME(3725), SEC_TO_TIME(3725.5), SEC_TO_TIME(-1.25), TIME_TO_SEC('01:02:03.5'), TIMEDIFF('12:00:00.5', '10:30:00'), TIME('2024-02-29 13:45:10.678'), TIME_FORMAT('13:04:05.123456', '%H %i %s %f')
SELECT DATE_FORMAT('2024-02-29 13:45:10.678912', '%f %s %H'), TIMESTAMPDIFF(MICROSECOND, '2024-01-01 00:00:00.5', '2024-01-01 00:00:01.25'), DATE_ADD('2024-01-01 00:00:00.9', INTERVAL 1 SECOND), '2024-01-01 00:00:00.5' + INTERVAL 1 MICROSECOND
--CREATE TABLE fd (id INT PRIMARY KEY, c1 DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3), c2 TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), c3 DATETIME DEFAULT CURRENT_TIMESTAMP, c4 TIMESTAMP NULL DEFAULT NULL)
INSERT INTO fd (id) VALUES (1)
SELECT LENGTH(c1), LENGTH(c2), LENGTH(c3), c4 FROM fd
UPDATE fd SET c4 = '2024-01-01 00:00:00.7' WHERE id = 1
SELECT LENGTH(c2), c4 FROM fd
SELECT COLUMN_NAME, COLUMN_TYPE, DATETIME_PRECISION FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'fd' ORDER BY ordinal_position
# the types and index options a schema written by another tool uses
CREATE TABLE ty1 (a INTEGER, b MEDIUMINT, c REAL, d NUMERIC(5,2), e DEC(4,1), f FIXED(4,1), g DOUBLE PRECISION, h NCHAR(3), i NVARCHAR(4), j CHARACTER(2), k CHARACTER VARYING(4))
CREATE TABLE ty2 (a INT UNSIGNED NOT NULL, b INT SIGNED, c DECIMAL(5,2) UNSIGNED, d FLOAT UNSIGNED, e DOUBLE UNSIGNED, f TEXT(100), g YEAR(4), h TIMESTAMP(3), i TIME(2), j DATETIME(6))
CREATE TABLE ty3 (a DECIMAL, b DECIMAL(6), c DEC(7,3))
INSERT INTO ty3 VALUES (1.5, 123456.7, 1.23456)
SELECT * FROM ty3
CREATE TABLE rl (x REAL, y DOUBLE)
INSERT INTO rl VALUES (0.1, 0.1)
SELECT x * 3, y * 3 FROM rl
INSERT INTO ty2 (a, c) VALUES (1, -1)
INSERT INTO ty2 (a, d) VALUES (1, -0.5)
INSERT INTO ty2 (a, e) VALUES (1, -2)
INSERT INTO ty2 (a, c, d, e) VALUES (1, 2.5, 3.5, 4.5)
SELECT a, c, d, e FROM ty2
SELECT COLUMN_NAME, COLUMN_TYPE, NUMERIC_PRECISION, NUMERIC_SCALE FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'ty2' ORDER BY ordinal_position
CREATE TABLE ix1 (a INT, b INT, c INT, PRIMARY KEY (a) USING BTREE, UNIQUE KEY ua (b) USING BTREE, KEY kc (c) USING HASH COMMENT 'ix', KEY kd USING BTREE (a, b) COMMENT 'two', INDEX (b) VISIBLE, UNIQUE INDEX ub (c) COMMENT 'u')
CREATE TABLE ix2 (a INT, b INT, CHECK (a > 0) NOT ENFORCED, CONSTRAINT c2 CHECK (b > 0) NOT ENFORCED, c INT CHECK (c > 0) NOT ENFORCED)
INSERT INTO ix2 VALUES (-1, -1, -1)
SELECT * FROM ix2
CREATE INDEX ixa ON ix1 (a) USING BTREE
ALTER TABLE ix1 ADD INDEX ixb USING BTREE (b) COMMENT 'x'
SELECT INDEX_NAME, NON_UNIQUE, COLUMN_NAME FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'ix1' ORDER BY index_name, seq_in_index
# the corners the planted bugs found (two-digit years, carries, the forms of a time, the units and formats one by one, the fraction of a time column)
--CREATE TABLE yy (id INT PRIMARY KEY, d DATE, dt DATETIME, t TIME)
INSERT INTO yy VALUES (1, '69-12-31', '240229134510', '1 02')
INSERT INTO yy VALUES (2, '70-01-01', '240229134510.5', '10:60:00')
