SELECT NOW(7)
SELECT DATE_ADD('2024-01-01', INTERVAL '1 2:3:4' DAY_SECOND), DATE_ADD('2024-01-01', INTERVAL '1 2:3' DAY_MINUTE), DATE_ADD('2024-01-01 00:00:00', INTERVAL '2:3' DAY_HOUR)
SELECT DATE_ADD('2024-01-01 00:00:00', INTERVAL '1:2:3' HOUR_MINUTE), DATE_ADD('2024-01-01 00:00:00', INTERVAL '1 2:3:4' MINUTE_SECOND)
SELECT EXTRACT(DAY_HOUR FROM '13:45:10'), EXTRACT(HOUR_MINUTE FROM '13:45:10'), EXTRACT(DAY_SECOND FROM '-13:45:10')
SELECT GET_FORMAT(DATE, 'USA'), GET_FORMAT(DATE, 'JIS'), GET_FORMAT(DATE, 'ISO'), GET_FORMAT(DATE, 'EUR'), GET_FORMAT(DATE, 'INTERNAL')
SELECT GET_FORMAT(DATETIME, 'USA'), GET_FORMAT(DATETIME, 'JIS'), GET_FORMAT(DATETIME, 'ISO'), GET_FORMAT(DATETIME, 'EUR'), GET_FORMAT(DATETIME, 'INTERNAL')
SELECT GET_FORMAT(TIME, 'USA'), GET_FORMAT(TIME, 'JIS'), GET_FORMAT(TIME, 'ISO'), GET_FORMAT(TIME, 'EUR'), GET_FORMAT(TIME, 'INTERNAL')
SELECT GET_FORMAT(TIMESTAMP, 'USA'), GET_FORMAT(DATE, NULL), GET_FORMAT(date, 'usa'), GET_FORMAT(DATE, 'x')
SELECT MAKETIME(-900, 0, 0), MAKETIME(-838, 59, 59), MAKETIME(838, 59, 59), MAKETIME(839, 0, 0), MAKETIME(-0, 5, 6), MAKETIME(1, 2, 3.456789123), MAKETIME(1, 2, -1), MAKETIME(1, -2, 3)
SELECT TIMESTAMP('2024-02-29 10:00:00', '-00:00:00.5'), TIMESTAMP('2024-02-29 10:00:00', '00:00:00.5'), TIMESTAMP('2024-02-29 10:00:00.25', '00:00:00.5')
SELECT TIME('13:45:10.1234567'), TIME('13:45:10.9999995'), MICROSECOND('13:45:10.1234567'), TIME('-00:00:00.5')
SELECT CAST('24' AS YEAR), CAST(0 AS YEAR), CAST('0' AS YEAR), CAST(1999 AS YEAR), CAST(70 AS YEAR), CAST(69 AS YEAR), CAST(2156 AS YEAR), CAST(1900 AS YEAR), CAST('abc' AS YEAR), CAST(NULL AS YEAR)
