SELECT ADDTIME(a, b), SUBTIME(a, b), TIMEDIFF(a, b), TIME_TO_SEC(a), SEC_TO_TIME(TIME_TO_SEC(a)), TIME(c), MICROSECOND(c) FROM tt ORDER BY a
--CREATE TABLE ct2 (a INT, b INT, UNIQUE KEY ua USING BTREE (a), KEY kb (b) INVISIBLE, KEY kc (a, b) KEY_BLOCK_SIZE=8, KEY kd (b) KEY_BLOCK_SIZE 4 COMMENT 'x' INVISIBLE)
